      .replace(/(\w+)\s*<\s*(\w+)/g, '$1 less than $2')
      .replace(/(\w+)\s*>=\s*(\w+)/g, '$1 ≥ $2')
      .replace(/(\w+)\s*<=\s*(\w+)/g, '$1 ≤ $2')
      .replace(/(\w+)\s*===?\s*(\w+)/g, '$1 equals $2')
      .replace(/(\w+)\s*!==?\s*(\w+)/g, '$1 not equals $2')
      .replace(/&&/g, 'AND')
      .replace(/\|\|/g, 'OR')
      .replace(/\(|\)/g, '');
    return condition;
  }
  
  if (/^elif\s+/.test(line)) {
